/**
 * RealWorld reports failures as `{"errors": {"<field>": ["<message>", ...]}}`.
 */
export type ErrorFields = Record<string, string[]>

export class ApiError extends Error {
  readonly statusCode: number
  readonly fields: ErrorFields

  constructor(statusCode: number, fields: ErrorFields) {
    super(`API error ${statusCode}`)
    this.name = 'ApiError'
    this.statusCode = statusCode
    this.fields = fields
  }

  static unauthorized(field: string, message: string): ApiError {
    return new ApiError(401, { [field]: [message] })
  }

  static forbidden(resource: string): ApiError {
    return new ApiError(403, { [resource]: ['forbidden'] })
  }

  static notFound(resource: string): ApiError {
    return new ApiError(404, { [resource]: ['not found'] })
  }

  static conflict(fields: ErrorFields): ApiError {
    return new ApiError(409, fields)
  }

  static unprocessable(fields: ErrorFields): ApiError {
    return new ApiError(422, fields)
  }
}

export const MISSING_TOKEN = ApiError.unauthorized('token', 'is missing')
export const INVALID_TOKEN = ApiError.unauthorized('token', 'is invalid')

