import { ApiError, type ErrorFields } from './errors.ts'

export const BLANK = "can't be blank"
export const INVALID = 'is invalid'
export const MIN_PASSWORD_LENGTH = 8
export const TOO_SHORT = `is too short (minimum is ${MIN_PASSWORD_LENGTH} characters)`

/** Collects per-field messages so a single response can report every problem at once. */
export class Validator {
  private readonly fields: ErrorFields = {}

  add(field: string, message: string): void {
    const messages = this.fields[field]
    if (messages) messages.push(message)
    else this.fields[field] = [message]
  }

  get hasErrors(): boolean {
    return Object.keys(this.fields).length > 0
  }

  throwIfInvalid(): void {
    if (this.hasErrors) throw ApiError.unprocessable(this.fields)
  }
}

type Payload = Record<string, unknown>

/** Reads the `{"<root>": {...}}` envelope every RealWorld payload uses. */
export function readEnvelope(body: unknown, root: string): Payload {
  const envelope = (body as Payload | undefined)?.[root]
  if (typeof envelope !== 'object' || envelope === null || Array.isArray(envelope)) {
    throw ApiError.unprocessable({ [root]: [BLANK] })
  }
  return envelope as Payload
}

/** Mandatory non-blank string: a missing key is as invalid as an empty one. */
export function requiredString(input: Payload, field: string, validator: Validator): string | undefined {
  const value = input[field]
  if (typeof value !== 'string' || value.trim() === '') {
    validator.add(field, BLANK)
    return undefined
  }
  return value.trim()
}

/** Optional string that must stay non-blank when the key is present (`null` is rejected). */
export function optionalString(input: Payload, field: string, validator: Validator): string | undefined {
  if (!(field in input)) return undefined
  return requiredString(input, field, validator)
}

/** Optional nullable string: an empty string is normalised to `null`. */
export function nullableString(
  input: Payload,
  field: string,
  validator: Validator,
): string | null | undefined {
  if (!(field in input)) return undefined
  const value = input[field]
  if (value === null) return null
  if (typeof value !== 'string') {
    validator.add(field, INVALID)
    return undefined
  }
  const trimmed = value.trim()
  return trimmed === '' ? null : trimmed
}

/** Password rules follow NIST 800-63B: at least 8 characters, no composition rules. */
export function password(
  input: Payload,
  field: string,
  validator: Validator,
  { required }: { required: boolean },
): string | undefined {
  if (!required && !(field in input)) return undefined
  const value = input[field]
  if (typeof value !== 'string' || value.trim() === '') {
    validator.add(field, BLANK)
    return undefined
  }
  if (value.length < MIN_PASSWORD_LENGTH) {
    validator.add(field, TOO_SHORT)
    return undefined
  }
  return value
}

/** Optional list of tag names; `null` is rejected, an empty array clears the tags. */
export function tagList(input: Payload, field: string, validator: Validator): string[] | undefined {
  if (!(field in input)) return undefined
  const value = input[field]
  if (!Array.isArray(value) || value.some((tag) => typeof tag !== 'string' || tag.trim() === '')) {
    validator.add(field, INVALID)
    return undefined
  }
  return [...new Set((value as string[]).map((tag) => tag.trim()))]
}

