import type { FastifyRequest, preHandlerHookHandler } from 'fastify'

import { prisma } from './db.ts'
import { invalidToken, missingToken } from './errors.ts'
import { verifyToken } from './security.ts'

export interface CurrentUser {
  id: number
  email: string
  username: string
  bio: string | null
  image: string | null
}

declare module 'fastify' {
  interface FastifyRequest {
    currentUser: CurrentUser | null
  }
}

/** RealWorld clients send `Authorization: Token <jwt>`; `Bearer` is accepted as well. */
function extractToken(request: FastifyRequest): string | null {
  const header = request.headers.authorization
  if (!header) return null
  const match = /^(?:token|bearer)\s+(.+)$/i.exec(header.trim())
  return match?.[1]?.trim() ?? null
}

async function resolveUser(request: FastifyRequest): Promise<{
  token: string | null
  user: CurrentUser | null
}> {
  const token = extractToken(request)
  if (!token) return { token: null, user: null }
  const payload = verifyToken(token)
  if (!payload) return { token, user: null }
  const user = await prisma.user.findUnique({
    where: { id: payload.id },
    select: { id: true, email: true, username: true, bio: true, image: true },
  })
  return { token, user }
}

export const requireAuth: preHandlerHookHandler = async (request) => {
  const { token, user } = await resolveUser(request)
  if (!token) throw missingToken()
  if (!user) throw invalidToken()
  request.currentUser = user
}

/** Endpoints that behave differently for signed-in users but never reject anonymous ones. */
export const optionalAuth: preHandlerHookHandler = async (request) => {
  const { user } = await resolveUser(request)
  request.currentUser = user
}

export function authenticatedUser(request: FastifyRequest): CurrentUser {
  if (!request.currentUser) throw missingToken()
  return request.currentUser
}

export function viewerId(request: FastifyRequest): number | null {
  return request.currentUser?.id ?? null
}

