import { signToken } from './security.ts'

/**
 * The shapes below describe the minimum a Prisma result must provide, so the
 * serializers accept any query that includes the relations they need.
 *
 * `followers` / `favorites` are always fetched filtered down to the current
 * viewer, which turns "is the list non-empty" into the `following` /
 * `favorited` flags.
 */
export interface ProfileSource {
  username: string
  bio: string | null
  image: string | null
  followers: unknown[]
}

export interface UserSource {
  id: number
  email: string
  username: string
  bio: string | null
  image: string | null
}

export interface ArticleSource {
  slug: string
  title: string
  description: string
  body: string
  createdAt: Date
  updatedAt: Date
  author: ProfileSource
  tags: { tag: { name: string } }[]
  favorites: unknown[]
  _count: { favorites: number }
}

export interface CommentSource {
  id: number
  body: string
  createdAt: Date
  updatedAt: Date
  author: ProfileSource
}

export function userResponse(user: UserSource) {
  return {
    user: {
      email: user.email,
      username: user.username,
      bio: user.bio,
      image: user.image,
      token: signToken({ id: user.id, username: user.username }),
    },
  }
}

export function profile(source: ProfileSource) {
  return {
    username: source.username,
    bio: source.bio,
    image: source.image,
    following: source.followers.length > 0,
  }
}

export function profileResponse(source: ProfileSource) {
  return { profile: profile(source) }
}

export function article(source: ArticleSource, { withBody }: { withBody: boolean }) {
  return {
    slug: source.slug,
    title: source.title,
    description: source.description,
    ...(withBody ? { body: source.body } : {}),
    tagList: source.tags.map((link) => link.tag.name).sort(),
    createdAt: source.createdAt.toISOString(),
    updatedAt: source.updatedAt.toISOString(),
    favorited: source.favorites.length > 0,
    favoritesCount: source._count.favorites,
    author: profile(source.author),
  }
}

export function articleResponse(source: ArticleSource) {
  return { article: article(source, { withBody: true }) }
}

/** List endpoints omit `body`; `articlesCount` is the total before pagination. */
export function articlesResponse(sources: ArticleSource[], articlesCount: number) {
  return {
    articles: sources.map((source) => article(source, { withBody: false })),
    articlesCount,
  }
}

export function comment(source: CommentSource) {
  return {
    id: source.id,
    createdAt: source.createdAt.toISOString(),
    updatedAt: source.updatedAt.toISOString(),
    body: source.body,
    author: profile(source.author),
  }
}

export function commentResponse(source: CommentSource) {
  return { comment: comment(source) }
}

export function commentsResponse(sources: CommentSource[]) {
  return { comments: sources.map(comment) }
}

