import type { FastifyInstance } from 'fastify'

import { authenticatedUser, requireAuth } from '../auth.ts'
import { prisma } from '../db.ts'
import { ApiError } from '../errors.ts'
import { hashPassword, verifyPassword } from '../security.ts'
import { userResponse } from '../serializers.ts'
import {
  nullableString,
  optionalString,
  password,
  readEnvelope,
  requiredString,
  Validator,
} from '../validation.ts'

const TAKEN = 'has already been taken'

/** Usernames and emails are unique across users; report both clashes at once. */
async function assertAvailable(
  username: string | undefined,
  email: string | undefined,
  excludeUserId?: number,
): Promise<void> {
  const conflicts = await prisma.user.findMany({
    where: {
      OR: [...(username ? [{ username }] : []), ...(email ? [{ email }] : [])],
      ...(excludeUserId === undefined ? {} : { NOT: { id: excludeUserId } }),
    },
    select: { username: true, email: true },
  })
  if (conflicts.length === 0) return

  const fields: Record<string, string[]> = {}
  if (username && conflicts.some((user) => user.username === username)) fields['username'] = [TAKEN]
  if (email && conflicts.some((user) => user.email === email)) fields['email'] = [TAKEN]
  throw ApiError.conflict(fields)
}

export async function userRoutes(app: FastifyInstance): Promise<void> {
  // Registration
  app.post('/api/users', async (request, reply) => {
    const payload = readEnvelope(request.body, 'user')
    const validator = new Validator()
    const username = requiredString(payload, 'username', validator)
    const email = requiredString(payload, 'email', validator)
    const plainPassword = password(payload, 'password', validator, { required: true })
    validator.throwIfInvalid()

    await assertAvailable(username, email)
    const user = await prisma.user.create({
      data: {
        username: username!,
        email: email!,
        password: await hashPassword(plainPassword!),
      },
    })
    return reply.code(201).send(userResponse(user))
  })

  // Authentication
  app.post('/api/users/login', async (request) => {
    const payload = readEnvelope(request.body, 'user')
    const validator = new Validator()
    const email = requiredString(payload, 'email', validator)
    const plainPassword = requiredString(payload, 'password', validator)
    validator.throwIfInvalid()

    const user = await prisma.user.findUnique({ where: { email: email! } })
    if (!user || !(await verifyPassword(plainPassword!, user.password))) {
      throw ApiError.unauthorized('credentials', 'invalid')
    }
    return userResponse(user)
  })

  app.get('/api/user', { preHandler: requireAuth }, async (request) => {
    return userResponse(authenticatedUser(request))
  })

  app.put('/api/user', { preHandler: requireAuth }, async (request) => {
    const current = authenticatedUser(request)
    const payload = readEnvelope(request.body, 'user')
    const validator = new Validator()
    const username = optionalString(payload, 'username', validator)
    const email = optionalString(payload, 'email', validator)
    const plainPassword = password(payload, 'password', validator, { required: false })
    const bio = nullableString(payload, 'bio', validator)
    const image = nullableString(payload, 'image', validator)
    validator.throwIfInvalid()

    await assertAvailable(username, email, current.id)
    const user = await prisma.user.update({
      where: { id: current.id },
      data: {
        ...(username === undefined ? {} : { username }),
        ...(email === undefined ? {} : { email }),
        ...(plainPassword === undefined ? {} : { password: await hashPassword(plainPassword) }),
        ...(bio === undefined ? {} : { bio }),
        ...(image === undefined ? {} : { image }),
      },
    })
    return userResponse(user)
  })
}

