import type { FastifyInstance } from 'fastify'

import { authenticatedUser, optionalAuth, requireAuth, viewerId } from '../auth.ts'
import { prisma } from '../db.ts'
import { ApiError } from '../errors.ts'
import { profileResponse } from '../serializers.ts'

interface UsernameParams {
  username: string
}

/** Loads a profile with the viewer's follow state attached. */
async function findProfile(username: string, followerId: number | null) {
  const user = await prisma.user.findUnique({
    where: { username },
    include: { followers: { where: { followerId: followerId ?? -1 } } },
  })
  if (!user) throw ApiError.notFound('profile')
  return user
}

export async function profileRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: UsernameParams }>(
    '/api/profiles/:username',
    { preHandler: optionalAuth },
    async (request) => {
      return profileResponse(await findProfile(request.params.username, viewerId(request)))
    },
  )

  app.post<{ Params: UsernameParams }>(
    '/api/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request) => {
      const follower = authenticatedUser(request)
      const target = await findProfile(request.params.username, follower.id)
      if (target.id !== follower.id) {
        await prisma.follow.upsert({
          where: { followerId_followedId: { followerId: follower.id, followedId: target.id } },
          create: { followerId: follower.id, followedId: target.id },
          update: {},
        })
      }
      return profileResponse(await findProfile(request.params.username, follower.id))
    },
  )

  app.delete<{ Params: UsernameParams }>(
    '/api/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request) => {
      const follower = authenticatedUser(request)
      const target = await findProfile(request.params.username, follower.id)
      await prisma.follow.deleteMany({
        where: { followerId: follower.id, followedId: target.id },
      })
      return profileResponse(await findProfile(request.params.username, follower.id))
    },
  )
}

