import { randomBytes } from 'node:crypto'

import type { FastifyInstance } from 'fastify'

import { authenticatedUser, optionalAuth, requireAuth, viewerId } from '../auth.ts'
import { prisma } from '../db.ts'
import { ApiError } from '../errors.ts'
import { articleResponse, articlesResponse } from '../serializers.ts'
import { optionalString, readEnvelope, requiredString, tagList, Validator } from '../validation.ts'

const DEFAULT_LIMIT = 20

interface SlugParams {
  slug: string
}

interface ListQuery {
  tag?: string
  author?: string
  favorited?: string
  limit?: string
  offset?: string
}

/**
 * Relations needed by the serializer. `followers` and `favorites` are narrowed to
 * the viewer so their emptiness answers "following?" and "favorited?".
 */
function articleInclude(viewer: number | null) {
  return {
    author: { include: { followers: { where: { followerId: viewer ?? -1 } } } },
    tags: { include: { tag: true } },
    favorites: { where: { userId: viewer ?? -1 } },
    _count: { select: { favorites: true } },
  }
}

const NEWEST_FIRST = [{ createdAt: 'desc' as const }, { id: 'desc' as const }]

function slugify(title: string): string {
  const base = title
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 100)
  return base || 'article'
}

/** Duplicate titles are allowed, so collisions get a short random suffix. */
async function uniqueSlug(title: string): Promise<string> {
  const base = slugify(title)
  let candidate = base
  while (await prisma.article.findUnique({ where: { slug: candidate }, select: { id: true } })) {
    candidate = `${base}-${randomBytes(4).toString('hex')}`
  }
  return candidate
}

async function replaceTags(articleId: number, names: string[]): Promise<void> {
  await prisma.articleTag.deleteMany({ where: { articleId } })
  for (const name of names) {
    const tag = await prisma.tag.upsert({ where: { name }, create: { name }, update: {} })
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id } })
  }
}

async function loadArticle(slug: string, viewer: number | null) {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: articleInclude(viewer),
  })
  if (!article) throw ApiError.notFound('article')
  return article
}

function paginationOf(query: ListQuery): { take: number; skip: number } {
  const parse = (value: string | undefined, fallback: number): number => {
    const parsed = Number(value)
    return value !== undefined && Number.isInteger(parsed) && parsed >= 0 ? parsed : fallback
  }
  return { take: parse(query.limit, DEFAULT_LIMIT), skip: parse(query.offset, 0) }
}

export async function articleRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Querystring: ListQuery }>(
    '/api/articles',
    { preHandler: optionalAuth },
    async (request) => {
      const { tag, author, favorited } = request.query
      const viewer = viewerId(request)
      const where = {
        ...(tag ? { tags: { some: { tag: { name: tag } } } } : {}),
        ...(author ? { author: { username: author } } : {}),
        ...(favorited ? { favorites: { some: { user: { username: favorited } } } } : {}),
      }
      const { take, skip } = paginationOf(request.query)

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(viewer),
          orderBy: NEWEST_FIRST,
          take,
          skip,
        }),
        prisma.article.count({ where }),
      ])
      return articlesResponse(articles, articlesCount)
    },
  )

  app.get<{ Querystring: ListQuery }>(
    '/api/articles/feed',
    { preHandler: requireAuth },
    async (request) => {
      const viewer = authenticatedUser(request)
      const where = { author: { followers: { some: { followerId: viewer.id } } } }
      const { take, skip } = paginationOf(request.query)

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(viewer.id),
          orderBy: NEWEST_FIRST,
          take,
          skip,
        }),
        prisma.article.count({ where }),
      ])
      return articlesResponse(articles, articlesCount)
    },
  )

  app.get<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: optionalAuth },
    async (request) => {
      return articleResponse(await loadArticle(request.params.slug, viewerId(request)))
    },
  )

  app.post('/api/articles', { preHandler: requireAuth }, async (request, reply) => {
    const author = authenticatedUser(request)
    const payload = readEnvelope(request.body, 'article')
    const validator = new Validator()
    const title = requiredString(payload, 'title', validator)
    const description = requiredString(payload, 'description', validator)
    const body = requiredString(payload, 'body', validator)
    const tags = tagList(payload, 'tagList', validator)
    validator.throwIfInvalid()

    const created = await prisma.article.create({
      data: {
        slug: await uniqueSlug(title!),
        title: title!,
        description: description!,
        body: body!,
        authorId: author.id,
      },
    })
    if (tags?.length) await replaceTags(created.id, tags)

    return reply.code(201).send(articleResponse(await loadArticle(created.slug, author.id)))
  })

  app.put<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      if (existing.authorId !== user.id) throw ApiError.forbidden('article')

      const payload = readEnvelope(request.body, 'article')
      const validator = new Validator()
      const title = optionalString(payload, 'title', validator)
      const description = optionalString(payload, 'description', validator)
      const body = optionalString(payload, 'body', validator)
      const tags = tagList(payload, 'tagList', validator)
      validator.throwIfInvalid()

      const updated = await prisma.article.update({
        where: { id: existing.id },
        data: {
          ...(title === undefined ? {} : { title, slug: await uniqueSlug(title) }),
          ...(description === undefined ? {} : { description }),
          ...(body === undefined ? {} : { body }),
        },
      })
      if (tags !== undefined) await replaceTags(existing.id, tags)

      return articleResponse(await loadArticle(updated.slug, user.id))
    },
  )

  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      if (existing.authorId !== user.id) throw ApiError.forbidden('article')

      await prisma.article.delete({ where: { id: existing.id } })
      return reply.code(204).send()
    },
  )

  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: user.id, articleId: existing.id } },
        create: { userId: user.id, articleId: existing.id },
        update: {},
      })
      return articleResponse(await loadArticle(existing.slug, user.id))
    },
  )

  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      await prisma.favorite.deleteMany({ where: { userId: user.id, articleId: existing.id } })
      return articleResponse(await loadArticle(existing.slug, user.id))
    },
  )
}

