        slug: await uniqueSlug(title!),
        title: title!,
        description: description!,
        body: body!,
        authorId: author.id,
      },
    })
    if (tags?.length) await replaceTags(created.id, tags)

    return reply.code(201).send(articleResponse(await loadArticle(created.slug, author.id)))
  })

  app.put<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      if (existing.authorId !== user.id) throw ApiError.forbidden('article')

      const payload = readEnvelope(request.body, 'article')
      const validator = new Validator()
      const title = optionalString(payload, 'title', validator)
      const description = optionalString(payload, 'description', validator)
      const body = optionalString(payload, 'body', validator)
      const tags = tagList(payload, 'tagList', validator)
      validator.throwIfInvalid()

      const updated = await prisma.article.update({
        where: { id: existing.id },
        data: {
          ...(title === undefined ? {} : { title, slug: await uniqueSlug(title) }),
          ...(description === undefined ? {} : { description }),
          ...(body === undefined ? {} : { body }),
        },
      })
      if (tags !== undefined) await replaceTags(existing.id, tags)

      return articleResponse(await loadArticle(updated.slug, user.id))
    },
  )

  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      if (existing.authorId !== user.id) throw ApiError.forbidden('article')

      await prisma.article.delete({ where: { id: existing.id } })
      return reply.code(204).send()
    },
  )

  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: user.id, articleId: existing.id } },
        create: { userId: user.id, articleId: existing.id },
        update: {},
      })
      return articleResponse(await loadArticle(existing.slug, user.id))
    },
  )

  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request) => {
      const user = authenticatedUser(request)
      const existing = await loadArticle(request.params.slug, user.id)
      await prisma.favorite.deleteMany({ where: { userId: user.id, articleId: existing.id } })
      return articleResponse(await loadArticle(existing.slug, user.id))
    },
  )
}

