import type { FastifyInstance } from 'fastify'

import { authenticatedUser, optionalAuth, requireAuth, viewerId } from '../auth.ts'
import { prisma } from '../db.ts'
import { ApiError } from '../errors.ts'
import { commentResponse, commentsResponse } from '../serializers.ts'
import { readEnvelope, requiredString, Validator } from '../validation.ts'

interface SlugParams {
  slug: string
}

interface CommentParams extends SlugParams {
  id: string
}

function commentInclude(viewer: number | null) {
  return {
    author: { include: { followers: { where: { followerId: viewer ?? -1 } } } },
  }
}

async function articleIdOf(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } })
  if (!article) throw ApiError.notFound('article')
  return article.id
}

export async function commentRoutes(app: FastifyInstance): Promise<void> {
  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/comments',
    { preHandler: requireAuth },
    async (request, reply) => {
      const author = authenticatedUser(request)
      const articleId = await articleIdOf(request.params.slug)

      const payload = readEnvelope(request.body, 'comment')
      const validator = new Validator()
      const body = requiredString(payload, 'body', validator)
      validator.throwIfInvalid()

      const comment = await prisma.comment.create({
        data: { body: body!, articleId, authorId: author.id },
        include: commentInclude(author.id),
      })
      return reply.code(201).send(commentResponse(comment))
    },
  )

  app.get<{ Params: SlugParams }>(
    '/api/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (request) => {
      const articleId = await articleIdOf(request.params.slug)
      const comments = await prisma.comment.findMany({
        where: { articleId },
        include: commentInclude(viewerId(request)),
        orderBy: { id: 'asc' },
      })
      return commentsResponse(comments)
    },
  )

  app.delete<{ Params: CommentParams }>(
    '/api/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (request, reply) => {
      const user = authenticatedUser(request)
      const articleId = await articleIdOf(request.params.slug)

      const commentId = Number(request.params.id)
      const comment = Number.isInteger(commentId)
        ? await prisma.comment.findFirst({ where: { id: commentId, articleId } })
        : null
      if (!comment) throw ApiError.notFound('comment')
      if (comment.authorId !== user.id) throw ApiError.forbidden('comment')

      await prisma.comment.delete({ where: { id: comment.id } })
      return reply.code(204).send()
    },
  )
}

