import Fastify, { type FastifyInstance } from 'fastify'

import { config } from './config.ts'
import { ApiError } from './errors.ts'
import { articleRoutes } from './routes/articles.ts'
import { commentRoutes } from './routes/comments.ts'
import { profileRoutes } from './routes/profiles.ts'
import { tagRoutes } from './routes/tags.ts'
import { userRoutes } from './routes/users.ts'

export function buildApp(): FastifyInstance {
  const app = Fastify({ logger: { level: config.logLevel } })

  app.decorateRequest('currentUser', null)

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.statusCode).send({ errors: error.fields })
    }
    // Malformed or unsupported request bodies are validation failures, not crashes.
    if (typeof error.code === 'string' && error.code.startsWith('FST_ERR_CTP')) {
      return reply.code(422).send({ errors: { body: ['is invalid'] } })
    }
    request.log.error({ err: error }, 'unhandled error')
    return reply.code(500).send({ errors: { server: ['internal error'] } })
  })

  app.setNotFoundHandler((_request, reply) => {
    return reply.code(404).send({ errors: { route: ['not found'] } })
  })

  app.get('/health', async () => ({ status: 'ok' }))

  app.register(userRoutes)
  app.register(profileRoutes)
  app.register(articleRoutes)
  app.register(commentRoutes)
  app.register(tagRoutes)

  return app
}

